import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User, UserTeam, Transaction } from '../types';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
  register: (userData: RegisterData) => Promise<void>;
  updateProfile: (data: Partial<User>) => Promise<void>;
  getUserTeams: () => UserTeam[];
  getTransactionHistory: () => Transaction[];
}

interface RegisterData {
  username: string;
  email: string;
  password: string;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Mock user data for development
  const mockUser: User = {
    id: 'user-1',
    username: 'john_doe',
    email: 'john@example.com',
    avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150',
    balance: 2500,
    totalWinnings: 15000,
    totalContests: 45,
    winRate: 65.5,
    badges: [
      {
        id: 'badge-1',
        name: 'First Win',
        description: 'Won your first contest',
        icon: '🏆',
        earnedAt: '2024-01-15'
      },
      {
        id: 'badge-2',
        name: 'High Scorer',
        description: 'Scored 200+ points in a contest',
        icon: '⚡',
        earnedAt: '2024-02-20'
      }
    ],
    createdAt: '2024-01-01'
  };

  useEffect(() => {
    // Simulate API call to check if user is logged in
    const checkAuthStatus = async () => {
      try {
        // In a real app, this would be an API call
        const token = localStorage.getItem('token');
        if (token) {
          setUser(mockUser);
        }
      } catch (error) {
        console.error('Auth check failed:', error);
      } finally {
        setLoading(false);
      }
    };

    checkAuthStatus();
  }, []);

  const login = async (email: string, password: string) => {
    try {
      setLoading(true);
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      // Mock successful login
      localStorage.setItem('token', 'mock-token');
      setUser(mockUser);
    } catch (error) {
      throw new Error('Login failed');
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    setUser(null);
  };

  const register = async (userData: RegisterData) => {
    try {
      setLoading(true);
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      // Mock successful registration
      const newUser: User = {
        ...mockUser,
        id: 'user-new',
        username: userData.username,
        email: userData.email,
        balance: 1000,
        totalWinnings: 0,
        totalContests: 0,
        winRate: 0,
        badges: []
      };
      
      localStorage.setItem('token', 'mock-token');
      setUser(newUser);
    } catch (error) {
      throw new Error('Registration failed');
    } finally {
      setLoading(false);
    }
  };

  const updateProfile = async (data: Partial<User>) => {
    if (!user) return;
    
    try {
      setLoading(true);
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 500));
      
      setUser({ ...user, ...data });
    } catch (error) {
      throw new Error('Profile update failed');
    } finally {
      setLoading(false);
    }
  };

  const getUserTeams = (): UserTeam[] => {
    // Mock user teams data
    return [];
  };

  const getTransactionHistory = (): Transaction[] => {
    // Mock transaction history
    return [
      {
        id: 'txn-1',
        userId: user?.id || '',
        type: 'deposit',
        amount: 1000,
        status: 'completed',
        description: 'Wallet deposit',
        createdAt: '2024-03-01T10:00:00Z'
      },
      {
        id: 'txn-2',
        userId: user?.id || '',
        type: 'contest_entry',
        amount: -50,
        status: 'completed',
        description: 'Contest entry fee',
        createdAt: '2024-03-02T15:30:00Z',
        contestId: 'contest-1'
      }
    ];
  };

  const value = {
    user,
    loading,
    login,
    logout,
    register,
    updateProfile,
    getUserTeams,
    getTransactionHistory
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
